-- ePOS v1 schema. Source: PRD section 14.
-- Money columns are BIGINT rupiah (no decimals). Enums are VARCHAR + CHECK.
-- Do not edit this file once committed; add V<n>__*.sql instead.

CREATE TABLE users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          VARCHAR(100) NOT NULL,
    username      VARCHAR(50)  NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    role          VARCHAR(20)  NOT NULL,
    is_active     BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT ck_users_role CHECK (role IN ('OWNER', 'CASHIER'))
);

CREATE TABLE categories (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- Category names are unique regardless of letter case ("Sembako" = "sembako").
CREATE UNIQUE INDEX uk_categories_name_ci ON categories (lower(name));

CREATE TABLE products (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku         VARCHAR(50)  NOT NULL,
    barcode     VARCHAR(50),
    name        VARCHAR(150) NOT NULL,
    category_id BIGINT       NOT NULL,
    unit        VARCHAR(20)  NOT NULL,
    cost_price  BIGINT       NOT NULL,
    sell_price  BIGINT       NOT NULL,
    stock       INTEGER      NOT NULL DEFAULT 0,
    min_stock   INTEGER      NOT NULL DEFAULT 0,
    is_active   BOOLEAN      NOT NULL DEFAULT TRUE,
    version     BIGINT       NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_products_sku UNIQUE (sku),
    CONSTRAINT uk_products_barcode UNIQUE (barcode),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT,
    CONSTRAINT ck_products_unit CHECK (unit IN ('PCS', 'KG', 'LITER', 'BUNGKUS', 'DUS')),
    CONSTRAINT ck_products_cost_price CHECK (cost_price >= 0),
    CONSTRAINT ck_products_sell_price CHECK (sell_price >= 0),
    CONSTRAINT ck_products_stock CHECK (stock >= 0),
    CONSTRAINT ck_products_min_stock CHECK (min_stock >= 0)
);

CREATE INDEX idx_products_name ON products (name);
CREATE INDEX idx_products_category ON products (category_id);

CREATE TABLE sales (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_no     VARCHAR(30) NOT NULL,
    cashier_id     BIGINT      NOT NULL,
    subtotal       BIGINT      NOT NULL,
    discount       BIGINT      NOT NULL DEFAULT 0,
    total          BIGINT      NOT NULL,
    payment_method VARCHAR(20) NOT NULL,
    paid           BIGINT      NOT NULL,
    change_amount  BIGINT      NOT NULL,
    status         VARCHAR(20) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_sales_invoice_no UNIQUE (invoice_no),
    CONSTRAINT fk_sales_cashier FOREIGN KEY (cashier_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT ck_sales_subtotal CHECK (subtotal >= 0),
    CONSTRAINT ck_sales_discount CHECK (discount >= 0),
    CONSTRAINT ck_sales_total CHECK (total >= 0),
    CONSTRAINT ck_sales_paid CHECK (paid >= total),
    CONSTRAINT ck_sales_change_amount CHECK (change_amount = paid - total),
    CONSTRAINT ck_sales_payment_method CHECK (payment_method IN ('CASH')),
    CONSTRAINT ck_sales_status CHECK (status IN ('COMPLETED'))
);

CREATE INDEX idx_sales_created_at ON sales (created_at);
CREATE INDEX idx_sales_cashier_created_at ON sales (cashier_id, created_at);

CREATE TABLE sale_items (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sale_id      BIGINT       NOT NULL,
    product_id   BIGINT       NOT NULL,
    product_name VARCHAR(150) NOT NULL,  -- snapshot at time of sale
    unit         VARCHAR(20)  NOT NULL,  -- snapshot at time of sale
    price        BIGINT       NOT NULL,  -- snapshot at time of sale
    qty          INTEGER      NOT NULL,
    subtotal     BIGINT       NOT NULL,
    CONSTRAINT fk_sale_items_sale FOREIGN KEY (sale_id) REFERENCES sales (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sale_items_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT ck_sale_items_price CHECK (price >= 0),
    CONSTRAINT ck_sale_items_qty CHECK (qty > 0),
    CONSTRAINT ck_sale_items_subtotal CHECK (subtotal = price * qty)
);

CREATE INDEX idx_sale_items_sale ON sale_items (sale_id);
CREATE INDEX idx_sale_items_product ON sale_items (product_id);

CREATE TABLE stock_movements (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id   BIGINT       NOT NULL,
    type         VARCHAR(20)  NOT NULL,
    qty          INTEGER      NOT NULL,  -- positive (in) or negative (out)
    stock_before INTEGER      NOT NULL,
    stock_after  INTEGER      NOT NULL,
    reason       VARCHAR(20),            -- only for ADJUSTMENT
    note         VARCHAR(255),
    sale_id      BIGINT,                 -- only for SALE
    user_id      BIGINT       NOT NULL,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_stock_movements_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT fk_stock_movements_sale FOREIGN KEY (sale_id) REFERENCES sales (id) ON DELETE RESTRICT,
    CONSTRAINT fk_stock_movements_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT ck_stock_movements_type CHECK (type IN ('IN', 'SALE', 'ADJUSTMENT')),
    CONSTRAINT ck_stock_movements_reason CHECK (
        reason IS NULL OR reason IN ('RUSAK', 'KEDALUWARSA', 'HILANG', 'SALAH_HITUNG', 'LAINNYA')),
    CONSTRAINT ck_stock_movements_qty CHECK (qty <> 0),
    CONSTRAINT ck_stock_movements_balance CHECK (stock_after = stock_before + qty),
    CONSTRAINT ck_stock_movements_stock_after CHECK (stock_after >= 0),
    CONSTRAINT ck_stock_movements_sale_link CHECK ((type = 'SALE') = (sale_id IS NOT NULL))
);

CREATE INDEX idx_stock_movements_product_created_at ON stock_movements (product_id, created_at);
CREATE INDEX idx_stock_movements_sale ON stock_movements (sale_id);

-- Single-row table: the store has exactly one settings record (id = 1).
CREATE TABLE store_settings (
    id             BIGINT       PRIMARY KEY,
    store_name     VARCHAR(100) NOT NULL,
    address        VARCHAR(255),
    phone          VARCHAR(30),
    receipt_footer VARCHAR(255),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_store_settings_single_row CHECK (id = 1)
);

